<div class="section-heading"><div><div class="eyebrow">Atendimento monitorado</div><h1>Conversas do WhatsApp</h1><p class="text-secondary mb-0">Veja quando o bot está atendendo e assuma as conversas que precisam de uma pessoa.</p></div></div><div class="card"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Cliente</th><th>Última mensagem</th><th>Estado</th><th>Atualização</th><th></th></tr></thead><tbody><?php foreach($conversations as $c):$displayName=!empty($c['customer_name'])?$c['customer_name']:(!empty($c['contact_name'])?$c['contact_name']:$c['wa_id']);?><tr><td><strong><?=htmlspecialchars($displayName)?></strong><small class="d-block text-secondary"><?=htmlspecialchars($c['wa_id'])?></small></td><td><?=htmlspecialchars(mb_strimwidth((string)$c['last_body'],0,100,'…'))?></td><td><span class="badge <?=$c['status']==='waiting_human'?'text-bg-warning':($c['status']==='human'?'text-bg-primary':'text-bg-success')?>"><?=htmlspecialchars(['bot'=>'Bot ativo','waiting_human'=>'Aguardando humano','human'=>'Atendimento humano','closed'=>'Encerrada'][$c['status']]??$c['status'])?></span></td><td><?=date('d/m H:i',strtotime($c['last_message_at']))?></td><td><a class="btn btn-sm btn-outline-primary" href="/whatsapp/conversations/<?=(int)$c['id']?>">Abrir</a></td></tr><?php endforeach;?><?php if(!$conversations):?><tr><td colspan="5" class="empty-state">Nenhuma conversa recebida ainda.</td></tr><?php endif;?></tbody></table></div></div>
